import{_ as c,l as r,o as a,c as i,v as o,p as l,x as t,d,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"套接字选项","description":"","frontmatter":{"title":"套接字选项","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/socket-options.md","filePath":"cs/socket-options.md","lastUpdated":1789023840000}'),_={name:"cs/socket-options.md"};function P(E,e,S,T,h,m){const s=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="套接字选项" tabindex="-1">套接字选项 <a class="header-anchor" href="#套接字选项" aria-label="Permalink to &quot;套接字选项&quot;">​</a></h1><div class="epigraph"><p>setsockopt 把传输与缓冲旋钮暴露给应用：不延迟、保活、地址复用、时间戳，而不改系统调用号。</p><footer>—— 据 POSIX setsockopt；Stevens, <em>UNP</em>；Linux socket(7)、tcp(7)</footer></div><p><a href="/cs/rdma-os">上一课</a>留下的缺口接到本课。 <a href="/cs/kernel-tcp-impl">TCP 实现</a> 与 <a href="/cs/socket-buffers">缓冲</a> 已有内核对象。应用通过 <strong>套接字选项</strong> 触及它们，而不是重编内核。网络栈课序在此收口，下一单元回到内存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>默认 Nagle 合并小写；延迟 ACK 交互差。<code>TCP_NODELAY</code> 关 Nagle。<code>SO_REUSEADDR</code>/<code>SO_REUSEPORT</code> 管绑定。<code>SO_KEEPALIVE</code> 探活。<code>SO_TIMESTAMP</code> 把 RX 时间戳交用户。缺口：选项在 SOL_SOCKET vs IPPROTO_TCP 层；有的继承 listen，有的要在 connect 前设；与 <a href="/cs/napi">busy poll</a> 的 <code>SO_BUSY_POLL</code> 接头。本课不把每一选项写成 man 页拷贝。</p><p><span class="marginnote">TCP_QUICKACK、CORK、MAXSEG 是同一层的细旋钮。错误的 REUSEPORT 负载均衡会打乱 CPU 亲和。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>setsockopt(fd, level, opt, ...)</code> 改 <code>sock</code> 字段，后续 <code>tcp_sendmsg</code> 读这些字段。对照 <a href="/cs/file-locking">fcntl 文件锁</a>：一个管文件劝告锁，一个管传输行为。对照 sysctl：全局默认，选项是 per-fd 覆盖。对照 RDMA：verbs 不走这套。</p>',8)),(a(),l(p,null,{default:t(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22setsockopt%22%5D%20--%3E%20SK%5B%22sock%20%E5%AD%97%E6%AE%B5%22%5D%0A%20%20SK%20--%3E%20TCP%5B%22%E5%8F%91%E9%80%81%2FACK%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SK%20--%3E%20UDP%5B%22UDP%20%E7%BC%93%E5%86%B2%E4%B8%8E%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>选项把内核 TCP/UDP 的工程折中变成可调 ABI，使 HTTP 服务器与 SSH 能不同。它们不创造新协议。不要写成云负载均衡产品文档。与 netfilter：选项改端行为，不替代防火墙。</p><p>安全：有的选项要特权（如绑定低端口是另一件事，<code>IP_TRANSPARENT</code> 要 cap）。</p><p>实现上：SO_REUSEPORT 的哈希把同端口多监听器分流，和 RSS 一样怕连接不对称。TCP_USER_TIMEOUT 管未 ACK 数据的死亡，和 KEEPALIVE 探空闲不是一回事。 读法上只引用<a href="/cs/rdma-os">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>套接字选项</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MPTCP 的 sockopt 全集。不保证 Windows 同名选项语义——<a href="/cs/windows-nt-contrast">NT 对照</a> 后课。内存进阶第一课：页如何被反向找到，以便回收与 unmap。</p><p>版本字段会变，课序钉的是机制对象「套接字选项」，不是某一主线内核的结构体名。 后课默认：应用可用 sockopt 调缓冲与 TCP 行为。内核如何从物理页反查映射，下一课 rmap。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>sockopt 是 per-socket 的内核旋钮。</li><li>分层在 SOL_SOCKET 与协议级。</li><li>反向映射 rmap 是下一单元。</li><li>出处：Stevens <em>UNP</em>；Linux <code>socket(7)</code>、<code>tcp(7)</code>；POSIX。</li></ul>',11))])}const u=c(_,[["render",P]]);export{k as __pageData,u as default};
